theorem regular_unipotent_jordan_type (a b c : ∄) (h : a > b ∧≈b > c) :
  let d1 := a - b; d2 := b - c; d3 := a - c;
  let M := (1 - t^(d1+1)) * (1 - t^(d2+1)) * (1 - t^(d3+2)) /
           ((1 - t^d1) * (1 - t^d2) * (1 - t^d3));
  let m : ∄ → ∄ := λ j => (GenFunc.coeff M j).toNat;
  ∏ (u : GL₃ ₔ) (pi : irreducible_repr (lang λ a b c)),
    (pi u).jordanCanonicalForm =
      List.foldl (· ++ ·) [] (List.map (λ j => List.replicate (m j) (j+1)) ∂.range)

def planar_constellation (m : ℕ) := { p : planar_map // bipartite (m+1)-coloring p }
def leaf_stat (c : planar_constellation m) : ℕ := # leaves c

def dyck_peak_stat (w : DyckPath n) : ℕ := count (peaks w)

def greedy_tamari_genfun (m : ℕ) (t x : 𝔽) : 𝔽 :=
  ∑ (n : ℕ), (x^n / n!) * (∑ (w : DyckPath n), t^(dyck_peak_stat w))

assert refined_bijection : ∀ m ≥ 1,
  ∃ (φ : intervals (greedy_tamari_poset m) ≃ planar_constellation m),
    ∀ w,
      leaf_stat (φ w) = dyck_peak_stat w

assumption refined_bijection m
